MagickBooleanType LoadTileImage(Image *image, Image *tile_image, XCFDocInfo *inDocInfo, XCFLayerInfo *inLayerInfo, size_t data_length, ExceptionInfo *exception) {
    register PixelInfo *pixel_info;
    Quantum *q;
    size_t num_pixels;

    num_pixels = image->columns * image->rows;

    if (AcquirePixelInfo(image, &pixel_info) == MagickFalse)
        return MagickFalse;

    if (data_length < num_pixels)
        return MagickFalse;

    for (size_t i = 0; i < num_pixels; i++) {
        if (inDocInfo->image_type == GIMP_GRAY)
            pixel_info->red = pixel_info->green = pixel_info->blue = (Quantum) (image->pixels[i] * MaxQuantum);

        else if (inDocInfo->image_type == GIMP_RGB) {
            pixel_info->red = (Quantum) (image->pixels[i * 3] * MaxQuantum);
            pixel_info->green = (Quantum) (image->pixels[i * 3 + 1] * MaxQuantum);
            pixel_info->blue = (Quantum) (image->pixels[i * 3 + 2] * MaxQuantum);
        }

        pixel_info->opacity = inLayerInfo->alpha ? (Quantum) (image->pixels[i + 1] * MaxQuantum) : OpaqueOpacity;
    }

    q = SetImagePixels(tile_image, 0, 0, tile_image->columns, tile_image->rows, exception);

    if (q == (Quantum *) NULL)
        return MagickFalse;

    for (size_t i = 0; i < num_pixels; i++) {
        *q++ = pixel_info->red;
        *q++ = pixel_info->green;
        *q++ = pixel_info->blue;
        *q++ = pixel_info->opacity;
    }

    if (SyncImagePixels(tile_image, exception) == MagickFalse)
        return MagickFalse;

    return MagickTrue;
}

