MagickBooleanType LoadTileImage(Image *image, Image *tile_image, XCFDocInfo *inDocInfo, XCFLayerInfo *inLayerInfo, size_t data_length, ExceptionInfo *exception) {
    register ssize_t x;
    Quantum *q;
    ssize_t y;
    size_t width, height;
    ssize_t num_pixels;
    unsigned char *pixel_data = NULL;

    width = image->columns;
    height = image->rows;

    if (data_length != width * height * (inDocInfo->image_type == GIMP_GRAY ? 1 : 3)) {
        ThrowMagickException(exception, GetMagickModule(), ImageError, "InvalidDataLength", "data_length does not match expected size");
        return MagickFalse;
    }

    pixel_data = (unsigned char *) AcquireMemory(data_length);
    if (pixel_data == (unsigned char *) NULL) {
        ThrowMagickException(exception, GetMagickModule(), ResourceLimitError, "UnableToAcquireMemory", "Memory allocation for pixel data failed");
        return MagickFalse;
    }

    if (ReadBlob(image, data_length, pixel_data) != data_length) {
        RelinquishMemory(pixel_data);
        ThrowMagickException(exception, GetMagickModule(), CorruptImageError, "UnableToReadBlob", "Unable to read pixel data from the source image");
        return MagickFalse;
    }

    for (y = 0; y < (ssize_t) height; y++) {
        q = SetImagePixels(tile_image, 0, y, width, 1);
        if (q == (Quantum *) NULL)
            break;
        if (inDocInfo->image_type == GIMP_GRAY) {
            for (x = 0; x < (ssize_t) width; x++) {
                *q++ = ScaleCharToQuantum(pixel_data[x + y * width]);
                *q++ = ScaleCharToQuantum(pixel_data[x + y * width]);
                *q++ = ScaleCharToQuantum(pixel_data[x + y * width]);
                if (inLayerInfo->has_alpha)
                    *q++ = ScaleCharToQuantum(255);
            }
        }
        else {
            for (x = 0; x < (ssize_t) width; x++) {
                *q++ = ScaleCharToQuantum(pixel_data[3 * (x + y * width) + 0]);
                *q++ = ScaleCharToQuantum(pixel_data[3 * (x + y * width) + 1]);
                *q++ = ScaleCharToQuantum(pixel_data[3 * (x + y * width) + 2]);
                if (inLayerInfo->has_alpha)
                    *q++ = ScaleCharToQuantum(255);
            }
        }
        if (!SyncImagePixels(tile_image)) break;
    }

    RelinquishMemory(pixel_data);

    if (y < (ssize_t) height) {
        SyncImagePixels(tile_image);
        return MagickFalse;
    }

    return MagickTrue;
}

MagickBooleanType LoadTileImage(Image *image, Image *tile_image, XCFDocInfo *inDocInfo, XCFLayerInfo *inLayerInfo, size_t data_length, ExceptionInfo *exception) {
  register ssize_t x;
  ssize_t y;
  MagickBooleanType status;
  Quantum *pixels;
  size_t length;
  size_t width;
  size_t height;

  width = image->columns;
  height = image->rows;

  if ((inDocInfo->image_type == GIMP_GRAY) || (inDocInfo->image_type == GIMP_GRAYA))
    length = width;
  else
    length = width * 3;

  pixels = (Quantum *) AcquireQuantumMemory(length, sizeof(*pixels));
  if (pixels == (Quantum *) NULL)
    return (MagickFalse);

  for (y = 0; y < (ssize_t) height; y++) {
    register Quantum *q;

    q = pixels;
    for (x = 0; x < (ssize_t) width; x++) {
      if ((inDocInfo->image_type == GIMP_GRAY) || (inDocInfo->image_type == GIMP_GRAYA)) {
        *q++ = GetPixelRed(image, x, y);
        if ((inDocInfo->image_type == GIMP_GRAYA) && inLayerInfo->has_alpha)
          *q++ = inLayerInfo->alpha[x + y * inLayerInfo->width];
        else
          q++;
      }
      else {
        *q++ = GetPixelRed(image, x, y);
        *q++ = GetPixelGreen(image, x, y);
        *q++ = GetPixelBlue(image, x, y);
      }
    }

    status = SetImagePixels(tile_image, 0, y, width, 1, pixels, exception);
    if (status == MagickFalse)
      break;
  }

  pixels = (Quantum *) RelinquishMemory(pixels);
  return (status);
}

MagickBooleanType LoadTileImage(Image *image, Image *tile_image, XCFDocInfo *inDocInfo, XCFLayerInfo *inLayerInfo, size_t data_length, ExceptionInfo *exception) {
    MagickBooleanType success = MagickTrue;
    size_t width = tile_image->columns;
    size_t height = tile_image->rows;
    Quantum *pixels;
    size_t length;

    pixels = (Quantum *) AcquireQuantumMemory(width, sizeof(*pixels));
    if (!pixels) {
        ThrowMagickException(exception, GetMagickModule(), ResourceLimitError, "MemoryAllocationFailed", "Unable to allocate pixel storage", (unsigned long) width, "tiles");
        return MagickFalse;
    }

    length = width * height;

    if (inDocInfo->image_type == GIMP_GRAY) {
        /* Process gray image */
        for (size_t y = 0; y < height; y++) {
            for (size_t x = 0; x < width; x++) {
                size_t offset = y * width + x;
                pixels[x] = inLayerInfo->data[offset];
            }
            (void) SetImagePixels(tile_image, 0, y, width, 1, pixels);
            if (!SyncImagePixels(tile_image))
                success = MagickFalse;
        }
    }
    else if (inDocInfo->image_type == GIMP_RGB) {
        /* Process RGB image */
        for (size_t y = 0; y < height; y++) {
            for (size_t x = 0; x < width; x++) {
                size_t offset = y * width + x;
                pixels[offset] = inLayerInfo->data[offset * 3];     /* Red */
                pixels[offset] = inLayerInfo->data[offset * 3 + 1]; /* Green */
                pixels[offset] = inLayerInfo->data[offset * 3 + 2]; /* Blue */
            }
            (void) SetImagePixels(tile_image, 0, y, width, 1, pixels);
            if (!SyncImagePixels(tile_image))
                success = MagickFalse;
        }
    }
    else {
        /* Unsupported image type */
        success = MagickFalse;
    }

    RelinquishMagickMemory(pixels);
    return success;
}
